import RAPIER from '@dimforge/rapier3d-compat';
import { beforeAll, describe, expect, it } from 'vitest';
import { GAME_CONFIG } from '../config/GameConfig';
import type { Vec3 } from '../contracts/math';
import { HoleSceneBuilder } from '../core/HoleSceneBuilder';
import { candyFactoryCourse } from '../courses/data/candy-factory';
import { boostPad, cupAt, makeHole, pad, startAt, teleporter, v } from '../courses/data/layoutKit';
import { volcanoCourse } from '../courses/data/volcano';
import type { Course, Hole } from '../courses/types';
import { HoleSystem } from '../gameplay/HoleSystem';
import { GolfBallPhysics } from '../physics/GolfBallPhysics';
import { PhysicsWorld } from '../physics/PhysicsWorld';
import { HoleRuntime } from './HoleRuntime';

const STEP = 1 / 60;
const MASS = 0.75;
const RADIUS = GAME_CONFIG.physics.ballRadius;
const BALL_OPTIONS = { mass: MASS, friction: 0.5, restitution: 0.45, rollingResistance: 0, airResistance: 0 };

beforeAll(async () => {
  await RAPIER.init();
});

function holeOf(course: Course, id: string): Hole {
  const hole = course.holes.find((entry) => entry.id === id);
  if (!hole) throw new Error('missing hole ' + id);
  return hole;
}

/** Mirrors the fixed step Game runs: movers, then the sensor volumes, then the ball. */
class Rig {
  readonly physics = new PhysicsWorld();
  readonly builder = new HoleSceneBuilder();
  readonly runtime: HoleRuntime;
  readonly ball: GolfBallPhysics;
  readonly teleports: Vec3[] = [];

  constructor(hole: Hole, spawn: Vec3, velocity: Vec3 = { x: 0, y: 0, z: 0 }) {
    this.runtime = new HoleRuntime(this.physics, hole, this.builder);
    this.ball = new GolfBallPhysics(this.physics, spawn, BALL_OPTIONS);
    this.ball.body.setLinvel(velocity, true);
  }

  run(steps: number, stop?: () => boolean): void {
    for (let index = 0; index < steps; index += 1) {
      this.physics.step(STEP, (fixed) => {
        this.runtime.update(fixed);
        const effect = this.runtime.applyBallEffects(
          { position: this.ball.position, velocity: this.ball.velocity, radius: RADIUS },
          fixed,
          MASS,
        );
        if (!effect.changed) return;
        if (effect.position) {
          this.teleports.push({ ...effect.position });
          this.ball.body.setTranslation(effect.position, true);
        }
        this.ball.body.setLinvel(effect.velocity, true);
      });
      if (stop?.()) return;
    }
  }

  dispose(): void {
    this.runtime.dispose();
    this.builder.dispose();
    this.physics.dispose();
  }
}

describe('hazard volumes', () => {
  it('drops the ball into a volcano lava pool for two strokes instead of walling it off', () => {
    const hole = holeOf(volcanoCourse, 'volcano-3');
    const rig = new Rig(hole, { x: -4, y: 1.4, z: 0 });
    const holeSystem = new HoleSystem();
    const safe: Vec3 = { x: 0, y: 0.47, z: -11 };
    holeSystem.markSafePosition('p1', safe);

    // Two floors and three solid obstacles; the two lava pools must not add bodies.
    expect(rig.runtime.bodyCount).toBe(5);

    rig.run(90, () => rig.runtime.hazardAt(rig.ball.position) !== undefined);

    const hazard = rig.runtime.hazardAt(rig.ball.position);
    expect(hazard?.type).toBe('lava');
    expect(hazard?.id).toBe('volcano-3-lava-left');
    // The old cuboid collider parked the ball near 1.02; the sensor lets it reach the floor.
    expect(rig.ball.position.y).toBeLessThan(0.7);

    const resolution = rig.runtime.resolveHazard(hazard, holeSystem.getLastSafePosition('p1', hole.spawn));
    expect(resolution.penaltyStrokes).toBe(2);
    expect(resolution.resetPosition).toEqual(safe);

    rig.dispose();
  }, 30000);
});

describe('force volumes', () => {
  it('drags the ball sideways across the candy factory conveyor instead of blocking it', () => {
    const hole = holeOf(candyFactoryCourse, 'cf-07-conveyor-crunch');
    const start: Vec3 = { x: -3.5, y: 0.44, z: 10.2 };
    const rig = new Rig(hole, start, { x: 0, y: 0, z: 1.5 });

    // Three floors and the two pusher gates; the belt itself stays collider free.
    expect(rig.runtime.bodyCount).toBe(5);

    rig.run(30);

    const position = rig.ball.position;
    expect(position.x).toBeGreaterThan(start.x + 0.25);
    expect(rig.ball.velocity.x).toBeGreaterThan(0.8);
    // Still travelling down the fairway: a wall would have stopped or reversed the ball.
    expect(position.z).toBeGreaterThan(start.z + 0.3);

    rig.dispose();
  }, 30000);

  it('moves the ball to the exit coordinate of a layout kit teleporter', () => {
    const exit = v(3, 0.35, 18);
    const hole = makeHole(
      'kit-teleport',
      'Kit Teleport',
      3,
      startAt(0, 0),
      cupAt(0, 20),
      [pad('kit-floor', 0, 10, 8, 26, 'green')],
      [teleporter('kit-portal', 0, 6, exit)],
    );
    const rig = new Rig(hole, startAt(0, 0), { x: 0, y: 0, z: 3.5 });

    // Only the floor is solid.
    expect(rig.runtime.bodyCount).toBe(1);

    rig.run(200, () => rig.teleports.length > 0);

    expect(rig.teleports[0]).toEqual(exit);
    expect(rig.ball.position.z).toBeGreaterThan(17);
    expect(rig.ball.position.x).toBeCloseTo(exit.x, 1);

    rig.dispose();
  }, 30000);

  it('accelerates a rolling ball over a boost pad rather than bouncing it off one', () => {
    const hole = makeHole(
      'kit-boost',
      'Kit Boost',
      3,
      startAt(0, 0),
      cupAt(0, 18),
      [pad('kit-floor', 0, 9, 8, 24, 'green')],
      [boostPad('kit-boost-pad', 0, 6, 3, 2, 5, 14)],
    );
    const rig = new Rig(hole, startAt(0, 3), { x: 0, y: 0, z: 2 });

    expect(rig.runtime.bodyCount).toBe(1);

    rig.run(120, () => rig.ball.velocity.z > 4);

    expect(rig.ball.velocity.z).toBeGreaterThan(4);
    expect(rig.ball.position.z).toBeGreaterThan(5);

    rig.dispose();
  }, 30000);
});
